import json


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


responses = params.get("responses") or {}
todo_id = params.get("todo_id") or ""
outcome = "ignored"

if responses and todo_id:
    draft = read_json("PracticeManager/BookingDrafts/" + todo_id + ".json", None)
    if not draft:
        outcome = "ignored"
    else:
        decision = str(responses.get("q_decision") or "")
        enquirer_email = draft.get("enquirer_email") or ""
        first_name = draft.get("first_name") or "the patient"

        if decision == "Don't send":
            api.workq.comment(todo_id=todo_id, body="Marked as don't book. No patient was created and nothing was sent.")
            api.workq.complete(todo_id=todo_id)
            outcome = "not_booked"
        else:
            business_id = draft.get("business_id") or ""
            practitioner_id = draft.get("practitioner_id") or ""
            appointment_type_id = draft.get("appointment_type_id") or ""
            starts_at = draft.get("starts_at") or ""

            if not (business_id and practitioner_id and appointment_type_id and starts_at):
                api.workq.comment(todo_id=todo_id, body="This booking is missing required details and couldn't be created automatically. Book it manually in Cliniko.")
                outcome = "missing_details"
            else:
                patient_payload = {
                    "first_name": first_name,
                    "last_name": draft.get("last_name") or "",
                    "email": enquirer_email,
                }
                if draft.get("dob"):
                    patient_payload["date_of_birth"] = draft["dob"]

                try:
                    patient = api.connectors.invoke(server="cliniko-patients", tool="create_patient", args={"patient": patient_payload})
                    patient_id = str((patient or {}).get("id") or "")
                except Exception:
                    patient_id = ""

                if not patient_id:
                    api.workq.comment(todo_id=todo_id, body="Couldn't create the patient record in Cliniko. Nothing was booked.")
                    outcome = "patient_create_failed"
                else:
                    try:
                        appt = api.connectors.invoke(
                            server="cliniko-scheduling", tool="create_individual_appointment",
                            args={"appointment": {
                                "appointment_type_id": appointment_type_id,
                                "business_id": business_id,
                                "practitioner_id": practitioner_id,
                                "patient_id": patient_id,
                                "starts_at": starts_at,
                            }},
                        )
                        appointment_id = str((appt or {}).get("id") or "")
                    except Exception:
                        appointment_id = ""

                    if not appointment_id:
                        api.workq.comment(todo_id=todo_id, body="Created the patient (" + patient_id + ") but the booking itself failed. Book the appointment manually in Cliniko.")
                        outcome = "appointment_create_failed"
                    else:
                        intake_sent = False
                        template_id = draft.get("intake_form_template_id") or ""
                        if template_id:
                            try:
                                api.connectors.invoke(
                                    server="cliniko-clinical", tool="create_patient_form",
                                    args={"patient_form": {"patient_id": patient_id, "form_template_id": template_id}},
                                )
                                intake_sent = True
                            except Exception:
                                intake_sent = False

                        if enquirer_email:
                            edited = str(responses.get("q_edited_message") or "").strip()
                            body = edited if (decision == "Edit and send" and edited) else (
                                "Hi " + first_name + ", you're all booked in for " + starts_at + ". "
                                + ("We've also sent you an intake form to complete before your visit. " if intake_sent else "")
                                + "See you soon!"
                            )
                            try:
                                api.connectors.invoke(
                                    server="m365-mail-send", tool="send_email",
                                    args={"to": [enquirer_email], "subject": "You're booked in", "body": body, "contentType": "Text"},
                                )
                            except Exception:
                                pass

                        api.workq.comment(
                            todo_id=todo_id,
                            body="Booked " + first_name + " for " + starts_at + (" and sent the intake form." if intake_sent else "."),
                        )
                        api.workq.complete(todo_id=todo_id)
                        outcome = "booked"
